mapper.select:
SELECT * FROM meeting_rooms
WHERE
    status = 'active'

        AND capacity_min <= #{attendeesCount} AND capacity_max >= #{attendeesCount}


        AND building = #{building}


        AND floor = #{floor}


        AND facilities @> '{"projector": ${facilities.projector}}'

            AND (facilities->>'whiteboard')::int >= #{facilities.whiteboard, jdbcType=INTEGER}


            AND (facilities->>'power_sockets')::int >= #{facilities.powerSockets, jdbcType=INTEGER}

        AND facilities @> '{"coffee_break": ${facilities.coffeeBreak}}'


                facilities @> '{"special_notes": #{note}}'

mapper.insert:
INSERT INTO reservations (reservation_id, user_id, room_id, start_time, end_time, purpose, attendees) VALUES (#{reservationId}::uuid, #{userId}::uuid, #{roomId}::uuid, #{startTime}, #{endTime}, #{purpose}, '[
"${attendee}"
]'::jsonb) RETURNING *

INSERT INTO meeting_rooms (room_id, name, capacity_min, capacity_max, building, floor, status, created_by, created_at, updated_at, image, facilities) VALUES (#{roomId}::uuid, #{name}, #{capacityMin}, #{capacityMax}, #{building}, #{floor}, #{status}, #{createdBy}, #{createdAt}, #{updatedAt}, #{image}, '{"projector": ${facilities.projector}, "whiteboard": ${facilities.whiteboard}, "power_sockets": ${facilities.powerSockets}, "coffee_break": ${facilities.coffeeBreak}, "special_notes": [
"${note}"
]}'::jsonb)

mapper.update:
UPDATE reservations SET room_id = #{roomId}::uuid, start_time = #{startTime}, end_time = #{endTime}, purpose = #{purpose}, attendees = '[
"${attendee}"
]'::jsonb, version = #{version} WHERE reservation_id = #{reservationId}::uuid

UPDATE meeting_rooms SET name = #{name}, capacity_min = #{capacityMin}, capacity_max = #{capacityMax}, building = #{building}, floor = #{floor}, status = #{status}, created_by = #{createdBy}, created_at = #{createdAt}, updated_at = #{updatedAt}, image = #{image}, facilities = '{"projector": ${facilities.projector}, "whiteboard": ${facilities.whiteboard}, "power_sockets": ${facilities.powerSockets}, "coffee_break": ${facilities.coffeeBreak}, "special_notes": [
"${note}"
]}'::jsonb WHERE room_id = #{roomId}::uuid
